package main

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
	"testing"
)

func oldCleanNote(s string) string {
	ws := regexp.MustCompile(`\s+`)
	angle := regexp.MustCompile(`[<>]`)
	s = angle.ReplaceAllString(s, "")
	return strings.TrimSpace(ws.ReplaceAllString(s, " "))
}

func oldUniqueSorted(items []string) []string {
	var out []string
	for _, it := range items {
		seen := false
		for _, o := range out {
			if o == it {
				seen = true
				break
			}
		}
		if !seen {
			out = append(out, it)
		}
	}
	sort.Strings(out)
	return out
}

func scratchNotes(n int) []string {
	out := make([]string, n)
	for i := range out {
		out[i] = fmt.Sprintf("  order #%d <for> customer\t%d  ", i, i%13)
	}
	return out
}

func scratchTags(n int) []string {
	tags := []string{"gift", "express", "bulk", "promo", "fragile", "intl", "retail", "b2b"}
	out := make([]string, 0, n*3)
	for i := 1; i <= n; i++ {
		out = append(out, tags[i%len(tags)], tags[(i*3)%len(tags)], tags[(i*5)%len(tags)])
	}
	return out
}

func BenchmarkOldCleanNote(b *testing.B) {
	notes := scratchNotes(1000)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		for _, n := range notes {
			oldCleanNote(n)
		}
	}
}

func BenchmarkNewCleanNote(b *testing.B) {
	notes := scratchNotes(1000)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		for _, n := range notes {
			cleanNote(n)
		}
	}
}

func BenchmarkOldUniqueSorted(b *testing.B) {
	tags := scratchTags(1000)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		oldUniqueSorted(tags)
	}
}

func BenchmarkNewUniqueSorted(b *testing.B) {
	tags := scratchTags(1000)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		uniqueSorted(tags)
	}
}

